// `setup-skills`, offline part: write the `unity-mcp-cli` skill (cold-start workflow, RQL recipes, exit codes,
// references/ for depth) and `ai-game-dev-app` into an agent's skills folder. No editor, no server, no network.
// Idempotent: the same CLI writes the same bytes, and unchanged files are not rewritten. Library-safe.
// The plugin's own skills (one per tool) are generated by the editor; the command asks for them when one answers.

import * as fs from 'fs';
import * as path from 'path';
import { getAgentById, getAgentIds } from '../utils/agents.js';
import { buildGuideFiles } from './skill-guides.js';

export interface WriteCliSkillsOptions {
  /** The Unity project folder. */
  projectPath: string;
  /** The agent whose `skillsPath` receives the skills. */
  agentId: string;
}

export type WriteCliSkillsResult =
  | { kind: 'success'; success: true; skillsDir: string; filesWritten: string[] }
  | { kind: 'failure'; success: false; error: Error };

/** Write the CLI's own skills into the agent's skills folder under the project. Never throws. */
export function writeCliSkills(opts: WriteCliSkillsOptions): WriteCliSkillsResult {
  try {
    const agent = getAgentById(opts.agentId);
    if (!agent) throw new Error(`Unknown agent: "${opts.agentId}". Available agent IDs: ${getAgentIds().join(', ')}`);
    if (!agent.skillsPath) throw new Error(`Agent "${agent.name}" does not support skills.`);
    const skillsDir = path.join(opts.projectPath, agent.skillsPath);
    const files = buildGuideFiles();
    const filesWritten: string[] = [];
    for (const file of files) {
      const target = path.join(skillsDir, file.relativePath);
      if (fs.existsSync(target) && fs.readFileSync(target, 'utf-8') === file.content) continue;
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, file.content, 'utf-8');
      filesWritten.push(target);
    }
    return { kind: 'success', success: true, skillsDir, filesWritten };
  } catch (err) {
    return { kind: 'failure', success: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
}
